The JavaScript Array constructor property is used to return the constructor function for an array object. It only returns the reference of the function and does not return the name of the function. In JavaScript arrays, it returns the function Array(){ [native code] }.Syntax:  array.constructorReturn value:It returns the function reference i.e. function Array() { [native code] }.Example 1: In this example, the program returns the reference of the function (i.e. function Array() { [native code] } ).
            JavaScript

    // Function to be executed
function myGeeks() {

    // Create array
    let name = ["sahil", "Manas",
        "Sagar", "Harshit"];

    // Display constructor property
    console.log(name.constructor);
}
myGeeks();

Output[Function: Array]
Example 2: In this example, the program returns the reference of the function (i.e. function Array() { [native code] } ).
            JavaScript

    // Create new array
let arr = new Array("Geeks", "for", "Geeks");

// Display constructor property
console.log("arr.constructor:" + arr.constructor); 

Outputarr.constructor:function Array() { [native code] }
Example 3: In this example, the program returns the reference of the function (i.e. function Array() { [native code] } ).
            JavaScript

    // Create array 
let arr = new Array(5, 10, 15);

// Dislay constructor property
console.log("arr.constructor:" + arr.constructor); 

Outputarr.constructor:function Array() { [native code] }
